# ===================== Command: stats =====================

HELP_TEXTS["stats"] = """\
Computes basic statistics on CSV data.

Basic statistics includes mean, median, mode, standard deviation, sum, max and
min values. Note that some statistics are expensive to compute, so they must
be enabled explicitly. By default, the following statistics are reported for
*every* column in the CSV data: mean, max, min and standard deviation. The
default set of statistics corresponds to statistics that can be computed
efficiently on a stream of data (i.e., constant memory).

Computing statistics on a large file can be made much faster if you create
an index for it first with 'xsv index'.

Usage:
    xsv stats [options] [<input>]

stats options:
    -s, --select <arg>     Select a subset of columns to compute stats for.
                           See 'xsv select --help' for the format details.
                           This is provided here because piping 'xsv select'
                           into 'xsv stats' will disable the use of indexing.
    --everything           Show all statistics available.
    --mode                 Show the mode.
                           This requires storing all CSV data in memory.
    --cardinality          Show the cardinality.
                           This requires storing all CSV data in memory.
    --median               Show the median.
                           This requires storing all CSV data in memory.
    --nulls                Include NULLs in the population size for computing
                           mean and standard deviation.
    -j, --jobs <arg>       The number of jobs to run in parallel.
                           This works better when the given CSV data has
                           an index already created. Note that a file handle
                           is opened for each job.
                           When set to '0', the number of jobs is set to the
                           number of CPUs detected.
                           [default: 0]

Common options:
    -h, --help             Display this message
    -o, --output <file>    Write output to <file> instead of stdout.
    -n, --no-headers       When set, the first row will NOT be interpreted
                           as column names. i.e., They will be included
                           in statistics.
    -d, --delimiter <arg>  The field delimiter for reading CSV data.
                           Must be a single character. (default: ,)
"""

def _rust_float_repr(x):
    """Format a float like Rust's default {} formatting."""
    if x == 0:
        return "0"
    if math.isinf(x):
        return "inf" if x > 0 else "-inf"
    if math.isnan(x):
        return "NaN"
    if x == int(x) and abs(x) < 1e16:
        return str(int(x))
    # Python repr() gives shortest round-trip; Rust's default does the same for f64
    r = repr(x)
    return r


def _infer_type(val):
    # Returns 'NULL', 'Integer', 'Float', 'Unicode'
    if val == b"":
        return "NULL"
    try:
        text = val.decode('utf-8')
    except UnicodeDecodeError:
        return "Unicode"  # actually maybe something else?
    # Integer?
    if re.match(r'^[+-]?\d+$', text):
        try:
            int(text)
            return "Integer"
        except Exception:
            return "Unicode"
    # Float?
    try:
        f = float(text)
        if not (math.isnan(f) or math.isinf(f)):
            return "Float"
    except ValueError:
        pass
    return "Unicode"


def _combine_types(t1, t2):
    order = {"NULL": 0, "Integer": 1, "Float": 2, "Unicode": 3}
    return max(t1, t2, key=lambda x: order[x])


def cmd_stats(argv):
    opts = parse_args_for_command(argv,
        options=[
            ("-h", "--help", False, False),
            ("-o", "--output", True, None),
            ("-n", "--no-headers", False, False),
            ("-d", "--delimiter", True, ","),
            ("-s", "--select", True, None),
            (None, "--everything", False, False),
            (None, "--mode", False, False),
            (None, "--cardinality", False, False),
            (None, "--median", False, False),
            (None, "--nulls", False, False),
            ("-j", "--jobs", True, "0"),
        ],
        flags=[]
    )
    if opts["help"]:
        sys.stdout.write(HELP_TEXTS["stats"])
        return
    pos = opts["_positional"]
    path = pos[0] if pos else None
    delim = parse_delim(opts["delimiter"])
    show_mode = opts["everything"] or opts["mode"]
    show_card = opts["everything"] or opts["cardinality"]
    show_med = opts["everything"] or opts["median"]
    include_nulls = opts["nulls"]
    out = open_output(opts["output"])
    writer = CsvWriter(out, delimiter=b",")
    with open_input(path) as f:
        reader = CsvReader(f, delimiter=delim, flexible=True)
        first_rec = reader.read_record()
        if first_rec is None:
            header_row = ["field", "type", "sum", "min", "max", "min_length", "max_length", "mean", "stddev"]
            if show_med: header_row.append("median")
            if show_mode: header_row.append("mode")
            if show_card: header_row.append("cardinality")
            writer.write_record(header_row)
            return
        header = first_rec[0]
        if opts["no-headers"]:
            labels = [str(i + 1).encode() for i in range(len(header))]
            all_rows = [header]
            for rec in reader:
                all_rows.append(rec)
        else:
            labels = [h for h in header]
            all_rows = [r for r in reader]
        if opts["select"] is not None:
            selector = Selector(opts["select"])
            indices = selector.indices(header, no_headers=opts["no-headers"])
        else:
            indices = list(range(len(header)))
    ncols = len(header)
    stats = [{
        "type": "NULL",
        "sum": 0.0, "count": 0,
        "min_val": None, "max_val": None,
        "min_len": None, "max_len": None,
        "values": [],
    } for _ in range(ncols)]
    for rec in all_rows:
        for i in indices:
            v = rec[i] if i < len(rec) else b""
            s = stats[i]
            is_null = (v == b"")
            t = _infer_type(v)
            s["type"] = _combine_types(s["type"], t)
            if not is_null or include_nulls:
                s["count"] += 1
                try:
                    s["sum"] += float(v.decode('utf-8'))
                except (ValueError, UnicodeDecodeError):
                    pass
            if not is_null:
                if s["min_val"] is None or v < s["min_val"]:
                    s["min_val"] = v
                if s["max_val"] is None or v > s["max_val"]:
                    s["max_val"] = v
            ln = len(v) if is_null else _display_width(v)
            if s["min_len"] is None or ln < s["min_len"]:
                s["min_len"] = ln
            if s["max_len"] is None or ln > s["max_len"]:
                s["max_len"] = ln
            if show_mode or show_card or show_med:
                s["values"].append(v)
    header_row = ["field", "type", "sum", "min", "max", "min_length", "max_length", "mean", "stddev"]
    if show_med: header_row.append("median")
    if show_mode: header_row.append("mode")
    if show_card: header_row.append("cardinality")
    writer.write_record(header_row)
    for i in indices:
        s = stats[i]
        t = s["type"]
        row = [labels[i], t]
        # sum
        if t in ("Integer", "Float"):
            row.append(_rust_float_repr(s["sum"]))
        else:
            row.append("")
        # min, max, min_length, max_length
        row.append(s["min_val"] if s["min_val"] is not None else b"")
        row.append(s["max_val"] if s["max_val"] is not None else b"")
        row.append(str(s["min_len"]) if s["min_len"] is not None else "")
        row.append(str(s["max_len"]) if s["max_len"] is not None else "")
        # mean, stddev
        if t in ("Integer", "Float"):
            if s["count"] > 0:
                mean = s["sum"] / s["count"]
                # Need variance
                numeric_values = []
                for v in s["values"] if (show_mode or show_card or show_med) else []:
                    try:
                        numeric_values.append(float(v.decode('utf-8')))
                    except (ValueError, UnicodeDecodeError):
                        pass
                if not numeric_values:
                    # need to compute variance in a second pass
                    var_sum = 0.0
                    n = 0
                    for rec in all_rows:
                        v = rec[i] if i < len(rec) else b""
                        is_null = (v == b"")
                        if is_null and not include_nulls:
                            continue
                        try:
                            x = float(v.decode('utf-8'))
                        except (ValueError, UnicodeDecodeError):
                            continue
                        var_sum += (x - mean) ** 2
                        n += 1
                    stddev = math.sqrt(var_sum / n) if n > 0 else 0
                else:
                    n = len(numeric_values)
                    var_sum = sum((x - mean) ** 2 for x in numeric_values)
                    stddev = math.sqrt(var_sum / n) if n > 0 else 0
                row.append(_rust_float_repr(mean))
                row.append(_rust_float_repr(stddev))
            else:
                row.append("")
                row.append("")
        else:
            row.append("")
            row.append("")
        # median
        if show_med:
            if t in ("Integer", "Float"):
                nums = []
                for v in s["values"]:
                    if v == b"" and not include_nulls:
                        continue
                    try:
                        nums.append(float(v.decode('utf-8')))
                    except (ValueError, UnicodeDecodeError):
                        pass
                nums.sort()
                if nums:
                    nh = len(nums)
                    if nh % 2 == 1:
                        med = nums[nh // 2]
                    else:
                        med = (nums[nh // 2 - 1] + nums[nh // 2]) / 2
                    row.append(_rust_float_repr(med))
                else:
                    row.append("")
            elif t == "Unicode":
                strs = sorted([v for v in s["values"] if v != b""])
                if strs:
                    nh = len(strs)
                    if nh % 2 == 1:
                        row.append(strs[nh // 2])
                    else:
                        row.append(strs[nh // 2 - 1])
                else:
                    row.append("")
            else:
                row.append("")
        # mode
        if show_mode:
            vals_nonnull = [v for v in s["values"] if v != b""]
            if not vals_nonnull:
                row.append("N/A")
            else:
                from collections import Counter as _C
                counter = _C(vals_nonnull)
                # xsv "mode": only when there's a unique element with highest count?
                most = counter.most_common()
                if len(most) == 1:
                    row.append(most[0][0])
                else:
                    top_count = most[0][1]
                    top_items = [v for v, c in most if c == top_count]
                    if len(top_items) == 1:
                        row.append(top_items[0])
                    else:
                        row.append("N/A")
        # cardinality
        if show_card:
            unique = set(v for v in s["values"] if v != b"" or include_nulls)
            # but what does xsv do? It seems to exclude nulls.
            unique = set(v for v in s["values"] if v != b"")
            row.append(str(len(unique)))
        writer.write_record(row)
    writer.flush()
    if opts["output"]:
        out.close()
